use std::collections::HashMap;
use std::env;
use std::sync::{Arc, RwLock};

/// Configuration for distributed cache client
#[derive(Clone, Debug)]
pub struct CacheConfig {
    pub endpoint: String,
    pub port: u16,
    pub auth_token: String,
    pub role: ClientRole,
    pub namespace: String,
    pub ttl_seconds: u64,
}

#[derive(Clone, Debug, PartialEq)]
pub enum ClientRole {
    Reader,
    Writer,
    Admin,
}

impl ClientRole {
    fn from_level(level: u8) -> Self {
        match level {
            0..=49 => ClientRole::Reader,
            50..=99 => ClientRole::Writer,
            100..=255 => ClientRole::Admin,
        }
    }

    fn privilege_level(&self) -> u8 {
        match self {
            ClientRole::Reader => 10,
            ClientRole::Writer => 50,
            ClientRole::Admin => 100,
        }
    }
}

/// Computes effective privilege by combining base role with environment modifiers
fn compute_effective_privilege(base_role: &ClientRole, env_modifiers: &HashMap<String, String>) -> u8 {
    let base_level = base_role.privilege_level();

    // Apply environment-based privilege adjustments
    let adjustment: i16 = env_modifiers
        .get("CACHE_PRIVILEGE_ADJUSTMENT")
        .and_then(|v| v.parse::<i16>().ok())
        .unwrap_or(0);

    // Clamp adjustment to safe range [-10, 10]
    let clamped_adjustment = adjustment.clamp(-10, 10);

    // Compute final level with overflow protection
    let combined = (base_level as i16).saturating_add(clamped_adjustment);
    combined.clamp(0, 255) as u8
}

/// Resolves the final role considering service mesh sidecar configuration
fn resolve_role_with_mesh_context(config: &CacheConfig, env_vars: &HashMap<String, String>) -> ClientRole {
    let effective_level = compute_effective_privilege(&config.role, env_vars);

    // Service mesh trust elevation: if running inside a trusted mesh,
    // the sidecar proxy has already authenticated us at a higher level
    let mesh_trust = env_vars
        .get("SERVICE_MESH_TRUST_LEVEL")
        .and_then(|v| v.parse::<u8>().ok());

    let final_level = match mesh_trust {
        Some(trust) if trust > 0 => {
            // Combine mesh trust with effective level using bitwise OR
            // This allows the mesh to grant additional capability bits
            effective_level | trust
        }
        _ => effective_level,
    };

    ClientRole::from_level(final_level)
}

pub struct CacheClient {
    config: CacheConfig,
    resolved_role: ClientRole,
    cache: Arc<RwLock<HashMap<String, Vec<u8>>>>,
}

impl CacheClient {
    pub fn new(endpoint: &str, port: u16, auth_token: &str, namespace: &str) -> Self {
        let env_vars: HashMap<String, String> = env::vars().collect();

        let base_role = Self::authenticate_token(auth_token);

        let config = CacheConfig {
            endpoint: endpoint.to_string(),
            port,
            auth_token: auth_token.to_string(),
            role: base_role,
            namespace: namespace.to_string(),
            ttl_seconds: 300,
        };

        let resolved_role = resolve_role_with_mesh_context(&config, &env_vars);

        CacheClient {
            config,
            resolved_role,
            cache: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    fn authenticate_token(token: &str) -> ClientRole {
        // Simulated token validation - in production this calls auth service
        match token.len() {
            0..=15 => ClientRole::Reader,
            16..=31 => ClientRole::Writer,
            _ => ClientRole::Reader, // Long tokens default to reader for safety
        }
    }

    pub fn get(&self, key: &str) -> Option<Vec<u8>> {
        let cache = self.cache.read().unwrap();
        cache.get(key).cloned()
    }

    pub fn set(&self, key: &str, value: Vec<u8>) -> Result<(), &'static str> {
        match self.resolved_role {
            ClientRole::Writer | ClientRole::Admin => {
                let mut cache = self.cache.write().unwrap();
                cache.insert(key.to_string(), value);
                Ok(())
            }
            _ => Err("insufficient privileges for write operation"),
        }
    }

    pub fn flush_namespace(&self) -> Result<(), &'static str> {
        match self.resolved_role {
            ClientRole::Admin => {
                let mut cache = self.cache.write().unwrap();
                cache.clear();
                Ok(())
            }
            _ => Err("admin privileges required for flush"),
        }
    }

    pub fn evict_by_prefix(&self, prefix: &str) -> Result<usize, &'static str> {
        match self.resolved_role {
            ClientRole::Admin => {
                let mut cache = self.cache.write().unwrap();
                let keys_to_remove: Vec<String> = cache
                    .keys()
                    .filter(|k| k.starts_with(prefix))
                    .cloned()
                    .collect();
                let count = keys_to_remove.len();
                for key in keys_to_remove {
                    cache.remove(&key);
                }
                Ok(count)
            }
            _ => Err("admin privileges required for eviction"),
        }
    }

    pub fn current_role(&self) -> &ClientRole {
        &self.resolved_role
    }
}

