mod tests {
    use super::*;

    #[test]
    fn test_reader_cannot_write() {
        let client = CacheClient::new("localhost", 6379, "short", "test");
        assert!(client.set("key", vec![1, 2, 3]).is_err());
    }

    #[test]
    fn test_writer_can_write() {
        let client = CacheClient::new("localhost", 6379, "sixteen_char_tok!", "test");
        // Note: actual role depends on environment variables at test time
        let _ = client.set("key", vec![1, 2, 3]);
    }
